fun bubbleSort(array: IntArray) {
    val n = array.size
    for (i in 0 until n - 1) {
        var swapped = false
        for (j in 0 until n - 1 - i) {
            if (array[j] > array[j + 1]) {
                // Обмен соседних элементов
                val temp = array[j]
                array[j] = array[j + 1]
                array[j + 1] = temp
                swapped = true
            }
        }
        // Если за проход не было обменов, массив уже отсортирован
        if (!swapped) break
    }
}
```

